<script setup lang="ts">
import { nextTick, onUnmounted, ref } from 'vue';
import type { components, createIsmClient } from '@ism/api-client';
import PortalMaterialUploader from './PortalMaterialUploader.vue';
const props=defineProps<{client:ReturnType<typeof createIsmClient>}>();
const emit=defineEmits<{unauthorized:[]}>();
type Request=components['schemas']['AdmissionMaterialRequest'];
type Submit=components['schemas']['SubmitAdmissionMaterialRequest'];
const history=ref<components['schemas']['AdmissionMaterialRequestPageResponse']['data']>(),selected=ref<Request>();
const busy=ref(false),uploadBusy=ref(false),error=ref(''),notice=ref(''),confirmed=ref(false),pending=ref<Submit>();
const groups=ref<Record<number,{items:{uploadId:string}[];pending:boolean;count:number}>>({});
const panel=ref<HTMLElement>(),errorPanel=ref<HTMLElement>();let disposed=false;const calls=new Set<AbortController>();
const names={OPEN:'待提交材料',SUBMITTED:'已提交，待员工采纳',ACCEPTED:'已采纳（准入结果以发布为准）',CANCELLED:'索取已撤销'};
async function fail(text:string){if(disposed)return;error.value=text;await nextTick();errorPanel.value?.focus();}
function take<T>(result:{data?:{data:T};response:Response}):T{if(result.data)return result.data.data;if(result.response.status===401)emit('unauthorized');throw new Error(result.response.status===409?'索取或准入申请已变化，请刷新，联系邀请方重新确认。':result.response.status===403?'租户未开通准入材料协作。':result.response.status===404?'材料索取或文件当前不可访问。':'操作未成功，请稍后重试。');}
async function load(page=0){if(busy.value||uploadBusy.value||disposed)return;busy.value=true;error.value='';const call=new AbortController();calls.add(call);try{const result=await props.client.GET('/portal/admission-material-requests',{params:{query:{page,size:10}},signal:call.signal});if(disposed)return;history.value=take(result);if(selected.value){const current=history.value.items.find(item=>item.id===selected.value?.id);if(current&&current.state!=='OPEN'){selected.value=undefined;pending.value=undefined;groups.value={};notice.value='记录已更新，请查看当前材料处理状态。';}}}catch(e){await fail(e instanceof Error?e.message:'读取失败。');}finally{calls.delete(call);if(!disposed)busy.value=false;}}
async function select(item:Request){if(busy.value||uploadBusy.value||pending.value)return;if(selected.value&&Object.values(groups.value).some(group=>group.count))return fail('请先完成当前提交或取消当前填写，避免覆盖已选材料。');selected.value=item;groups.value={};confirmed.value=false;error.value='';notice.value='';await nextTick();panel.value?.focus();}
function cancel(){if(busy.value||uploadBusy.value||pending.value)return;selected.value=undefined;groups.value={};confirmed.value=false;}
async function submit(){if(!selected.value||busy.value||uploadBusy.value||disposed)return;if(!pending.value){if(!confirmed.value||selected.value.items.some((_,i)=>groups.value[i]?.items.length!==1||groups.value[i]?.pending))return fail('请为每项索取上传一份完整文件，并确认提交。');pending.value={version:selected.value.version,materials:selected.value.items.map((item,i)=>({type:item.type,uploadId:groups.value[i].items[0].uploadId}))};}busy.value=true;error.value='';const call=new AbortController();calls.add(call);let done=false;try{const result=await props.client.POST('/portal/admission-material-requests/{id}/submit',{params:{path:{id:selected.value.id}},body:pending.value,signal:call.signal});if(disposed)return;if(!result.data&&[400,403,404,409,410,422].includes(result.response.status))pending.value=undefined;const current=take(result);notice.value='准入材料已提交，等待员工采纳；这不代表准入审核通过。';selected.value=undefined;pending.value=undefined;groups.value={};done=true;}catch(e){await fail((e instanceof Error?e.message:'提交中断。')+(pending.value?' 结果未知，填写已锁定，请刷新核查或重试同一提交。':''));}finally{calls.delete(call);if(!disposed)busy.value=false;}if(done&&!disposed)await load(history.value?.page??0);}
async function download(item:Request,type:string,name:string){if(busy.value||uploadBusy.value||disposed)return;busy.value=true;error.value='';const call=new AbortController();calls.add(call);try{const result=await props.client.GET('/portal/admission-material-requests/{id}/materials/{type}/content',{params:{path:{id:item.id,type}},parseAs:'blob',signal:call.signal});if(disposed)return;if(!result.response.ok||!result.data){if(result.response.status===401)emit('unauthorized');throw new Error('文件不可用或无下载权限，请刷新核查。');}const url=URL.createObjectURL(result.data);try{const link=document.createElement('a');link.href=url;link.download=name;link.click();}finally{setTimeout(()=>URL.revokeObjectURL(url),1000);}}catch(e){await fail(e instanceof Error?e.message:'下载失败。');}finally{calls.delete(call);if(!disposed)busy.value=false;}}
onUnmounted(()=>{disposed=true;calls.forEach(c=>c.abort());pending.value=undefined;groups.value={};});
</script>
<template>
<section class="admission-materials" aria-labelledby="admission-material-title" :aria-busy="busy||uploadBusy">
 <div class="heading"><h2 id="admission-material-title">准入材料协作</h2><button class="secondary" :disabled="busy||uploadBusy" @click="load()">{{history?'刷新准入材料':'查看准入材料索取'}}</button></div>
 <p class="help">这里只展示邀请方明确发布的材料索取；未发布的内部申请和意见不公开。上传、员工采纳与准入审核是三个独立步骤。</p>
 <div v-if="error" ref="errorPanel" role="alert" tabindex="-1" class="error">{{error}}</div><p v-if="notice" role="status">{{notice}}</p><p v-if="busy" role="status">正在处理准入材料…</p>
 <form v-if="selected" ref="panel" tabindex="-1" aria-label="提交准入材料" @submit.prevent="submit">
  <h3>申请 {{selected.applicationNo}} 的材料索取</h3><p class="instruction">{{selected.instruction}}</p>
  <fieldset :disabled="busy||!!pending"><legend>本次索取材料</legend><div v-for="(item,index) in selected.items" :key="item.type"><h4>{{index+1}}. {{item.name}}</h4><PortalMaterialUploader :client="client" :index="index" :remaining="1" purpose="admission" :disabled="busy||uploadBusy||!!pending" @busy="uploadBusy=$event" @change="groups[index]=$event" @unauthorized="emit('unauthorized')"/></div><label class="confirm"><input v-model="confirmed" type="checkbox" :disabled="uploadBusy" required/>确认本次材料完整，提交后等待员工采纳</label></fieldset>
  <button :disabled="busy||uploadBusy">{{pending?'重试同一准入材料提交':'确认提交准入材料'}}</button><button type="button" class="secondary" :disabled="busy||uploadBusy||!!pending" @click="cancel">取消当前填写</button>
 </form>
 <template v-if="history"><p v-if="!history.items.length" class="help">暂无对本企业发布的材料索取。</p><article v-for="item in history.items" :key="item.id"><h3>{{item.applicationNo}} · {{names[item.state]}}</h3><p class="instruction">{{item.instruction}}</p><p v-if="item.closeNote" class="instruction">撤销说明：{{item.closeNote}}</p><ul><li v-for="material in item.items" :key="material.type">{{material.name}}<template v-if="material.fileName"> · {{material.fileName}} <button type="button" class="secondary" :disabled="busy||uploadBusy" @click="download(item,material.type,material.fileName)">下载已提交材料</button></template></li></ul><button v-if="item.state==='OPEN'" class="secondary" :disabled="busy||uploadBusy||!!pending" @click="select(item)">填写本次准入材料</button></article><div class="heading"><button class="secondary" :disabled="busy||uploadBusy||history.page===0" @click="load(history.page-1)">上一页材料索取</button><span>第 {{history.page+1}} 页，共 {{history.total}} 条</span><button class="secondary" :disabled="busy||uploadBusy||(history.page+1)*history.size>=history.total" @click="load(history.page+1)">下一页材料索取</button></div></template>
</section>
</template>
<style scoped>
.admission-materials{margin-top:28px;padding-top:24px;border-top:1px solid #dce4ed;min-width:0;overflow-wrap:anywhere}.heading{display:flex;flex-wrap:wrap;gap:12px;align-items:center;justify-content:space-between}.instruction{white-space:pre-wrap;overflow-wrap:anywhere}fieldset{min-width:0;border:1px solid #8295ab;padding:12px;border-radius:8px}.confirm{display:flex;flex-direction:row;gap:10px;align-items:center;min-height:44px}.confirm input{width:20px;height:20px;min-height:20px;flex:none}button{margin:8px 8px 8px 0}article{border-bottom:1px solid #dce4ed}
</style>
